  "summary_ko": "소년이 창문에 가장 가까운 테이블을 뚫고 지나감",
  "claims": [
    {
      "id": "R2.S1",
      "evidence": "The boy walks through the table closest to the window",
      "symptom_ko": "소년이 테이블을 관통하여 걸어감",
      "is_anomaly": true,
      "specificity": "specific",
      "target_evidence": "The boy",
      "explicit_detail_evidence": [
        "walks through the table closest to the window"
      ],
      "missing_details_ko": ""
    }
  ]
}

{
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "target_relation": "same_interaction",
      "reference_claim_ids": [
        "R1.S1"
      ],
      "reference_evidence": "The boy jumps off of the floor and not \"off of the able\" like the prompt says.",
      "candidate_evidence": "Boy jumps and passes directly through the solid cafeteria bench and table surface onto the floor.",
      "basis": "explicit_separation",
      "reason_ko": "R1은 소년이 테이블이 아닌 바닥에서 점프를 시작해 넘어지는 프롬프트 미준수 결함을 다루는 반면, C1은 소년이 점프하여 단단한 벤치와 테이블 표면을 그대로 통과해 바닥으로 내려앉는 관통 물리 결함을 지적하므로 구체적인 결함 양상이 서로 분리됩니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "target_relation": "same_interaction",
      "reference_claim_ids": [
        "R1.S1"
      ],
      "reference_evidence": "The boy jumps off of the floor and not \"off of the able\" like the prompt says.",
      "candidate_evidence": "The running boy jumps onto and through the cafeteria table, morphing awkwardly and sliding smoothly under it without collision or normal interaction.",
      "basis": "explicit_separation",
      "reason_ko": "R1은 소년이 테이블이 아닌 바닥에서 뛰어오른다는 결함인 반면, C2는 소년이 테이블 위 및 속으로 뛰어들며 모핑되고 테이블 아래로 미끄러져 들어간다는 구체적인 관통/모핑 결함을 기술하므로 서로 다른 구체적 이상 현상으로 분리됩니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C3",
      "target_relation": "different",
      "reference_claim_ids": [
        "R1.S2"
      ],
      "reference_evidence": "The boy also doesn't twist his ankle, he just falls.",
      "candidate_evidence": "다른 소년은 점프 후 발로 착지하지 않고 평지에서 멈추어 걸어옴",
      "basis": "explicit_separation",
      "reason_ko": "R1은 점프 후 넘어지는 소년('The boy')을 대상으로 하는 반면, C3은 '다른 소년'을 명시적으로 지목하여 대상 엔티티 자체가 다릅니다."
    }
  ]
}

